# Surah Al-Isra (chapter 17) — part 8: ayat 71-80 (IDs 2100-2109)
SURAH = 17

ENTRIES = {
2100: (
"جس دن ہم تمام انسانوں کو ان کے پیشوا سمیت بلائیں گے — پس جسے اس کی کتاب دائیں ہاتھ میں دی گئی وہ اپنی کتاب پڑھیں گے — اور ان پر ہلکے سے بھی ظلم نہیں کیا جائے گا",
"""۱۔ قیامت میں ہر قوم اپنے پیشوا کے ساتھ اٹھے گی؛ دائیں ہاتھ والے اپنی پاک کتاب پڑھیں گے؛ ان پر کوئی ظلم نہیں۔
۲۔ ’’يَوْمَ نَدْعُو كُلَّ أُنَاسٍ بِإِمَامِهِمْ فَمَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ فَأُولَٰئِكَ يَقْرَءُونَ كِتَابَهُمْ وَلَا يُظْلَمُونَ فَتِيلًا‘‘ — جس دن ہم تمام انسانوں کو ان کے پیشوا سمیت بلائیں گے — پس جسے اس کی کتاب دائیں ہاتھ میں دی گئی وہ اپنی کتاب پڑھیں گے — اور ان پر ہلکے سے بھی ظلم نہیں کیا جائے گا — یعنی جس دن ہم سب لوگوں کو ان کے پیشوا کے ساتھ بلائیں گے — پس جس کی کتاب دائیں ہاتھ میں دی گئی وہ اپنی کتاب پڑھیں گے اور ان پر ایک دھاگے کی مقدار بھی ظلم نہیں ہو گا۔
۳۔ عملی سبق: اپنے امام کی اطاعت کرو؛ قیامت میں بہترین انجام ان کے لیے ہے جو اچھے عمل والے ہیں۔"""
),
2101: (
"اور جو اس دنیا میں اندھا ہے وہ آخرت میں بھی اندھا اور راستہ سے زیادہ گمراہ ہو گا",
"""۱۔ جو دنیا کی حقیقت نہ دیکھے وہ آخرت میں بھی اندھا اور بھٹکا ہوا ہو گا۔
۲۔ ’’وَمَن كَانَ فِي هَٰذِهِ أَعْمَىٰ فَهُوَ فِي الْآخِرَۃِ أَعْمَىٰ وَأَضَلُّ سَبِيلًا‘‘ — اور جو اس دنیا میں اندھا ہے وہ آخرت میں بھی اندھا اور راستہ سے زیادہ گمراہ ہو گا — یعنی جو اس دنیا میں اندھا رہا وہ آخرت میں بھی اندھا اور زیادہ بھٹکنے والا ہو گا۔
۳۔ عملی سبق: دل کی بصیرت حاصل کرو؛ حقیقت دیکھنے والے آخرت میں روشن راہ پاتے ہیں۔"""
),
2102: (
"اور وہ یقیناً آپ کو اس وحی سے فتنہ میں ڈالنے کی کوشش کر رہے تھے جو ہم نے آپ کی طرف وحی کی — تاکہ آپ ہمارے اوپر کچھ اور گھڑیں — اور تب وہ آپ کو اپنا دوست بنا لیتے",
"""۱۔ مشرکین کا منصوبہ: نبیؐ کو وحی سے دور کرکے اپنی طرف گھسیٹنا؛ اللہ نے آپؐ کو ثابت قدم رکھا۔
۲۔ ’’وَإِن كَادُوا لَيَفْتِنُونَكَ عَنِ الَّذِي أَوْحَيْنَا إِلَيْكَ لِتَفْتَرِيَ عَلَيْنَا غَيْرَهُ وَإِذًا لَّاتَّخَذُوكَ خَلِيلًا‘‘ — اور وہ یقیناً آپ کو اس وحی سے فتنہ میں ڈالنے کی کوشش کر رہے تھے جو ہم نے آپ کی طرف وحی کی — تاکہ آپ ہمارے اوپر کچھ اور گھڑیں — اور تب وہ آپ کو اپنا دوست بنا لیتے — یعنی وہ تو آپ کو اس وحی سے فتنے میں ڈالنے کے قریب تھے جو ہم نے آپ کی طرف وحی کی تاکہ آپ ہمارے اوپر کچھ اور افترا کریں — اور پھر وہ آپ کو اپنا خلیل بنا لیتے۔
۳۔ عملی سبق: حق پر ڈٹے رہیں؛ دشمنوں کو راضی کرنے کے لیے سچائی نہ بدلیں۔"""
),
2103: (
"اور اگر ہم آپ کو ثابت قدم نہ رکھتے تو یقیناً آپ ان کی طرف تھوڑی سی مائل ہو جاتے",
"""۱۔ اللہ کی مدد ہی نبیؐ کو ثابت قدم رکھتی ہے؛ تھوڑی سی مائل ہونا بھی نقصان دہ ہوتا۔
۲۔ ’’وَلَوْلَا أَن ثَبَّتْنَاكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْئًا قَلِيلًا‘‘ — اور اگر ہم آپ کو ثابت قدم نہ رکھتے تو یقیناً آپ ان کی طرف تھوڑی سی مائل ہو جاتے — یعنی اگر ہم آپ کو ثابت قدم نہ رکھتے تو آپ ان کی طرف تھوڑے سے مائل ہو جاتے۔
۳۔ عملی سبق: اللہ کی مدد کے بغیر کوئی بندہ ثابت قدم نہیں رہ سکتا؛ ہمیشہ اس سے مغفرت مانگو۔"""
),
2104: (
"پھر ہم آپ کو دونوں جہان کا عذاب چکھاتے — پھر آپ ہمارے مقابلے میں کوئی مددگار نہ پاتے",
"""۱۔ اگر نبیؐ تھوڑے مائل ہوتے تو دونوں جہاں کے عذاب چکھائے جاتے؛ کوئی نہ بچاتا۔
۲۔ ’’إِذًا لَّأَذَقْنَاكَ ضِعْفَ الْحَيَاۃِ وَضِعْفَ الْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًا‘‘ — پھر ہم آپ کو دونوں جہان کا عذاب چکھاتے — پھر آپ ہمارے مقابلے میں کوئی مددگار نہ پاتے — یعنی پھر ہم آپ کو دنیا اور آخرت کے عذاب کا دوگنا مزہ چکھاتے — پھر ہمارے مقابلے میں آپ کو کوئی مددگار نہ ملتا۔
۳۔ عملی سبق: حق پر ڈٹا رہو؛ عذاب سے بچنے کا واحد راستہ اللہ کی اطاعت ہے۔"""
),
2105: (
"اور وہ یقیناً آپ کو برسرِ زمین پریشان کرنے کی کوشش کر رہے تھے کہ آپ کو اس سرزمین سے نکال دیں — اور تب آپ کے بعد وہ خود بھی تھوڑی دیر ہی ٹھیر پاتے",
"""۱۔ مشرکین نے نبیؐ کو مکہ سے نکالنے کی سازش کی؛ اللہ نے انہیں تھوڑی دیر بعد مکے سے نکال دیا۔
۲۔ ’’وَإِن كَادُوا لَيَسْتَفِزُّونَكَ مِنَ الْأَرْضِ لِيُخْرِجُوكَ مِنْهَا وَإِذًا لَّا يَلْبَثُونَ خِلَافَكَ إِلَّا قَلِيلًا‘‘ — اور وہ یقیناً آپ کو برسرِ زمین پریشان کرنے کی کوشش کر رہے تھے کہ آپ کو اس سرزمین سے نکال دیں — اور تب آپ کے بعد وہ خود بھی تھوڑی دیر ہی ٹھیر پاتے — یعنی وہ تو آپ کو اس سرزمین سے نکالنے کی پوری کوشش کر رہے تھے — اور پھر آپ کے بعد وہ بھی تھوڑی دیر سے زیادہ وہاں نہ ٹھہرتے۔
۳۔ عملی سبق: اللہ نبیؐ کو چھوا نہیں؛ جو حق کے خلاف سازش کرے اس کا انجام تباہی ہے۔"""
),
2106: (
"یہ ہمارا دستور ہی رہا ہے ان رسولوں کا جو آپ سے پہلے ہم نے بھیجے — اور آپ ہمارے دستور میں کبھی تبدیلی نہیں پائیں گے",
"""۱۔ اللہ کا سنتِ قدیم: رسولوں کو ستایا گیا؛ قوم ہلاک؛ اللہ کا دستور نہیں بدلتا۔
۲۔ ’’سُنَّۃَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا‘‘ — یہ ہمارا دستور ہی رہا ہے ان رسولوں کا جو آپ سے پہلے ہم نے بھیجے — اور آپ ہمارے دستور میں کبھی تبدیلی نہیں پائیں گے — یعنی یہ ان رسولوں کا دستور تھا جو آپ سے پہلے بھیجے گئے — اور آپ ہمارے دستور میں کوئی تبدیلی نہیں پائیں گے۔
۳۔ عملی سبق: اللہ کا سنتِ قدیم یہی ہے؛ سبق سیکھا جائے اور نافرمانی ترک کی جائے۔"""
),
2107: (
"سورج کے ڈھلنے سے لے کر رات کی تاریکی تک نماز قائم رکھو — اور فجر کا قرآن — بے شک فجر کا قرآن گواہی دیا جاتا ہے",
"""۱۔ نمازوں کا وقت: دلوك الشمس (زوال / ظہر و عصر) سے تا غسق اللیل (مغرب و عشاء) اور فجر کا قرآن؛ فجر کی نماز گواہی دی جاتی ہے۔
۲۔ ’’أَقِمِ الصَّلَاۃَ لِدُلُوكِ الشَّمْسِ إِلَىٰ غَسَقِ اللَّيْلِ وَقُرْآنَ الْفَجْرِ إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا‘‘ — سورج کے ڈھلنے سے لے کر رات کی تاریکی تک نماز قائم رکھو — اور فجر کا قرآن — بے شک فجر کا قرآن گواہی دیا جاتا ہے — یعنی سورج کے ڈھلنے سے رات کی تاریکی تک نماز قائم کرو — اور فجر کی نماز — بے شک فجر کی نماز فرشتوں کے حاضر ہونے کی نماز ہے۔
۳۔ عملی سبق: پانچوں نمازوں کو ان کے وقت میں ادا کرو؛ فجر کی نماز کی فضیلت زیادہ ہے۔"""
),
2108: (
"اور رات کے کچھ حصے میں تہجد کی نماز آپ کے لیے خاص طور پر ادا کریں — امید ہے کہ آپ کا رب آپ کو مقامِ محمود تک پہنچائے گا",
"""۱۔ نبیؐ کے لیے تہجد خصوصی واجب؛ مقامِ محمود آپؐ کا بلند مقام — اللہ کی تمجید۔
۲۔ ’’وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَۃً لَّكَ عَسَىٰ أَن يَبْعَثَكَ رَبُّكَ مَقَامًا مَّحْمُودًا‘‘ — اور رات کے کچھ حصے میں تہجد کی نماز آپ کے لیے خاص طور پر ادا کریں — امید ہے کہ آپ کا رب آپ کو مقامِ محمود تک پہنچائے گا — یعنی رات کے کچھ حصے میں تہجد کی نماز آپ کے لیے خاص طور پر ادا کریں — امید ہے آپ کا رب آپ کو مقامِ محمود پر اٹھائے گا۔
۳۔ عملی سبق: رات کی نماز اللہ کا قرب دیتی ہے؛ نفل ادا کرتے رہیں۔"""
),
2109: (
"اور دعا کرو کہ اے میرے رب مجھے سچ کی جگہ داخل فرما اور سچ کی جگہ نکال — اور مجھے اپنی جانب سے ایک مددگار غلبہ عطا فرما",
"""۱۔ نبیؐ کی دعا: ہجرت اور جہاد میں سچائی کی منزل — مدینہ کا فتح؛ اللہ کی مدد۔
۲۔ ’’وَقُل رَّبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَل لِّي مِن لَّدُنكَ سُلْطَانًا نَّصِيرًا‘‘ — اور دعا کرو کہ اے میرے رب مجھے سچ کی جگہ داخل فرما اور سچ کی جگہ نکال — اور مجھے اپنی جانب سے ایک مددگار غلبہ عطا فرما — یعنی دعا کرو کہ اے میرے رب مجھے سچ کی منزل میں داخل کر اور سچ ہی کی منزل سے نکال — اور مجھے اپنی جانب سے ایک مددگار غلبہ عطا کر۔
۳۔ عملی سبق: ہر کام اللہ کی مدد سے شروع کرو؛ دشمن کے سامنے حق کا سہارا لو۔"""
),
}
